function [ceq c] = cr1(f,t_ult,t_out,u,y,stages)

timeL=0;

%equality
ceq = [];

timeL=0;

%inequality
for time=1+0+0:length(f(:,1))+0+0
c(time+timeL) = f(time,1)-40;
end
timeL=length(f(:,1));;
for time=1+0+0:length(f(:,1))+0+0
c(time+timeL) = f(time,3)-25;
end
timeL=length(f(:,1));;
for time=1+0+0:length(f(:,1))+0+0
c(time+timeL) = f(time,4)-10;
end
timeL=length(f(:,1));;
for time=1+0+0:length(f(:,1))+0+0
c(time+timeL) = f(time,1)+0 ;
end
timeL=length(f(:,1));;
for time=1+0+0:length(f(:,1))+0+0
c(time+timeL) = f(time,3)+0 ;
end
timeL=length(f(:,1));;
for time=1+0+0:length(f(:,1))+0+0
c(time+timeL) = f(time,4)+0 ;
end



end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
